// ===== Acumula resultados entre tentativas do loop de retry =====
// Cada tentativa do loop traz só os itens NOVOS encontrados nessa rodada
// (já filtrados contra a planilha pelo "Filter Already Saved"). Aqui somamos
// com tudo que já foi aceito nas tentativas anteriores desta mesma execução,
// guardado no Static Data do workflow (sobrevive entre os "saltos" do loop).

const staticData = $getWorkflowStaticData('global'); // 'global' = compartilhado entre TODOS os nodes (precisa ser visto pelo 'Montar Links ML')
const cfg = ($items('CONFIG ML')?.[0]?.json) ?? {};
const MIN_TOTAL = Number(cfg.min_total_final ?? 30);
const MAX_TOTAL_FINAL = Number(cfg.max_total_final ?? 40);
const MAX_TENTATIVAS = Number(cfg.max_tentativas ?? 20);

// Itens acumulados de tentativas anteriores (vazio na primeira tentativa)
const acumulados = Array.isArray(staticData.acumulados) ? staticData.acumulados : [];
const idsJaAcumulados = new Set(acumulados.map(j => j.link_compra).filter(Boolean));

// Soma os itens novos desta tentativa, evitando duplicar ID dentro do acumulado
const novosItens = $input.all().map(item => item.json || {});
for (const j of novosItens) {
  const id = String(j.link_compra || '').trim();
  if (id && idsJaAcumulados.has(id)) continue;
  if (id) idsJaAcumulados.add(id);
  acumulados.push(j);
  if (acumulados.length >= MAX_TOTAL_FINAL) break; // já bateu o teto, não precisa mais
}

const tentativaAtual = Number(staticData.tentativa || 0);

// Persiste o estado pra próxima volta do loop (se houver)
staticData.acumulados = acumulados;
staticData.tentativa = tentativaAtual + 1;

const atingiuPiso = acumulados.length >= MIN_TOTAL;
const atingiuTeto = acumulados.length >= MAX_TOTAL_FINAL;
const esgotouTentativas = (tentativaAtual + 1) >= MAX_TENTATIVAS;

const precisaContinuar = !atingiuPiso && !atingiuTeto && !esgotouTentativas;

// Retorna UM item de controle (não os produtos) — o "IF - Precisa Mais?" decide
// com base em precisaContinuar. Os produtos acumulados ficam só no Static Data
// até a hora de finalizar (lidos pelo node "Finalizar Acumulado").
return [{
  json: {
    precisaContinuar,
    total_acumulado: acumulados.length,
    tentativa: tentativaAtual + 1,
    max_tentativas: MAX_TENTATIVAS,
    min_total: MIN_TOTAL,
    max_total_final: MAX_TOTAL_FINAL,
  }
}];

// ============================================================
//  Nó: "Dedupe Precoce por ID"   (n8n Code node)
//  Modo: Run Once for All Items
//  Posição: ANTES do HTTP Request2 (API de afiliado = caro/bot)
//
//  CHAVE = id MLB extraído do link_compra (existe ANTES do scrape),
//  comparado contra a coluna "ID" da data table (mesmo id que o
//  "Filter Already Saved" usa). O link de afiliado salvo NÃO tem
//  o id, então a única chave confiável entre as duas fases é o id.
//  Também remove duplicados dentro da própria rodada.
// ============================================================

// ---- extractId: MESMA lógica do "Code in JavaScript2" (formato precisa bater) ----
function extractId(url) {
  if (!url) return '';
  const u = String(url);
  const m =
    u.match(/\/p\/([A-Z]+U?\d+)/i) ||
    u.match(/\/up\/([A-Z]+U?\d+)/i) ||
    u.match(/(MLB-?U?\d+)/i);
  return m ? m[1].replace('-', '').toUpperCase() : '';
}

// link cru do item nesta fase (Parse Preço grava em link_compra)
function linkOf(j) {
  return j.link_compra || j.link_produtos || j.link || j.url || '';
}

// id do item recém-encontrado (a partir do link cru)
function incomingId(j) {
  // se algum nó anterior já tiver setado um id, respeita; senão extrai do link
  const direct = String(j.ID || j.id || '').trim().toUpperCase();
  if (direct) return direct.replace('-', '');
  return extractId(linkOf(j));
}

// ---- 1. Conjunto de ids JÁ SALVOS na planilha (coluna "ID") ----
const existing = new Set();
let existingRows = [];
try {
  // Busca DIRETO na Data Table via API do n8n. O nó "Get Existing IDs" vinha
  // voltando vazio, e por isso o dedupe não barrava nada (mesmos produtos voltando).
  const _http = this.helpers.httpRequest;
  const _BASE = "https://n8n.gacompany.online/api/v1";
  const _KEY = "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9.eyJzdWIiOiI4ZTRiYThlOC01ZTg3LTRlY2EtYjg5NC0yNzgxNjA1Zjk3MzciLCJpc3MiOiJuOG4iLCJhdWQiOiJwdWJsaWMtYXBpIiwianRpIjoiNzllYTk2OGQtYTZhZC00NTI1LWE4YWYtNjRiODc2OTk1YzU0IiwiaWF0IjoxNzc5MjM4NDE5fQ.ohu4mPobwtuApSpWvuA-kReAEbU9zWIcxbT_6In5f4g";
  const _TABLE = "HHVRHOgRDCza0NBQ";
  // PAGINACAO: pega TODAS as linhas em blocos (sem teto de 250). Dedup de ids no
  // proprio loop torna eventuais sobreposicoes inofensivas; para quando uma pagina
  // nao traz id novo (fim, ou caso o backend ignore o offset -> degrada com seguranca).
  const _PAGE = 250;
  const _rows = [];
  const _seen = new Set();
  let _cursor = '';
  for (let _g = 0; _g < 500; _g++) {   // teto de seguranca: 500 * 200 = 100k linhas
    let _resp;
    try {
      _resp = await _http({
        method: "GET",
        url: `${_BASE}/data-tables/${_TABLE}/rows`,
        qs: _cursor ? { limit: _PAGE, cursor: _cursor } : { limit: _PAGE },
        headers: { "X-N8N-API-KEY": _KEY },
        json: true,
      });
    } catch (e) { break; }
    const _batch = (_resp && _resp.data) ? _resp.data : (Array.isArray(_resp) ? _resp : []);
    if (!_batch.length) break;
    let _novos = 0;
    for (const _r of _batch) {
      const _idk = String((_r && _r.id) != null ? _r.id : "");
      if (_idk && !_seen.has(_idk)) { _seen.add(_idk); _rows.push(_r); _novos++; }
    }
    if (_novos === 0) break;             // pagina sem id novo = acabou (ou offset ignorado)
    if (_batch.length < _PAGE) break;    // ultima pagina
    _cursor = (_resp && _resp.nextCursor) ? String(_resp.nextCursor) : '';
    if (!_cursor) break;
  }
  existingRows = _rows.map(r => ({ json: r }));
} catch (e) {
  try { existingRows = $('Get Existing IDs').all(); } catch (_) { existingRows = []; }
}
for (const r of existingRows) {
  const row = r.json || {};
  // A chave entre as duas fases é o id MLB, que fica DENTRO de link_compra.
  let id = extractId(row.link_compra || row.link_produtos || row.link || row.url || '');
  if (!id) id = String(row.id || row.ID || '').trim().toUpperCase().replace('-', '');
  if (!id) id = extractId(row.offerlink || row.link_produtos_afiliado || '');
  if (id) existing.add(id);
}

// ---- 2. Filtra os itens recém-encontrados ----
const seenThisRun = new Set();
const out = [];
let semId = 0, dropExisting = 0, dropDupRun = 0;

for (const it of $input.all()) {
  const j = it.json || {};
  const id = incomingId(j);

  if (!id) { semId++; out.push(it); continue; } // sem id não dá pra deduplicar: deixa passar

  if (existing.has(id))    { dropExisting++; continue; } // já está na planilha
  if (seenThisRun.has(id)) { dropDupRun++;   continue; } // repetido nesta rodada

  seenThisRun.add(id);
  out.push(it);
}

console.log(
  `[Dedupe Precoce] entrada=${$input.all().length} | ` +
  `na_planilha=${dropExisting} | dup_rodada=${dropDupRun} | ` +
  `sem_id=${semId} | novos=${out.length} | base_existente=${existing.size}`
);

return out;

// ===== Seleciona os MELHORES produtos do pool acumulado e entrega só eles =====
// Roda quando o loop de scraping termina. Ranqueia o pool por
// desconto + vendas + avaliacao + valor de comissao (com teto de preco),
// aplica o filtro de PALAVRAS PARECIDAS das ultimas execucoes e pega FINAL_PICK.
const cfg = ($items('CONFIG ML')?.[0]?.json) ?? {};
const staticData = $getWorkflowStaticData('global');
const acumulados = Array.isArray(staticData.acumulados) ? staticData.acumulados : [];

// Limpa o estado pra proxima execucao agendada comecar do zero
staticData.acumulados = [];
staticData.tentativa = 0;

// ---------- Knobs (ajustaveis no CONFIG ML) ----------
const FINAL_PICK   = Math.max(1, Number(cfg.final_pick ?? 3));        // quantos inserir por execucao
const MAX_PRICE    = Number(cfg.max_price ?? 0);                      // teto de preco (0 = sem teto) -> "nada muito caro"
const MIN_COMM_VAL = Number(cfg.min_commission_value ?? 0);          // comissao minima em R$ (estimada)
const W_SALES      = Number(cfg.w_sales ?? 0.35);
const W_RATING     = Number(cfg.w_rating ?? 0.20);
const W_DISCOUNT   = Number(cfg.w_discount ?? 0.25);
const W_COMMISSION = Number(cfg.w_commission ?? 0.20);
const WINDOW_H     = Number(cfg.similar_words_window_hours ?? 6);     // janela ~= 2 execucoes (3h cada)
const MIN_WORD_LEN = Number(cfg.similar_words_min_len ?? 4);
const STRICT_WORDS = String(cfg.similar_words_strict ?? 'false') === 'true'; // true = nunca completa com similar
const CATEGORIA    = String(cfg.ml_category_name ?? '').toLowerCase().trim();
const MIN_SALES    = Number(cfg.min_sales_final  ?? 10);   // vendas minimas: corta produto que "ninguem sabe o que e"
const MIN_RATING   = Number(cfg.min_rating_final ?? 4.0); // nota minima p/ "bem avaliado"

// Taxa de comissao por categoria (mesma tabela do "Code in JavaScript2") -> p/ ESTIMAR o valor em R$
function commissionRate(categoria) {
  let table = {};
  try {
    const raw = cfg.commission_rate_by_category;
    table = (raw && typeof raw === 'object') ? raw : JSON.parse(raw || '{}');
  } catch (e) {}
  const key = String(categoria || '').toLowerCase().trim();
  const r = Number(table[key]);
  return Number.isFinite(r) ? r : Number(cfg.commission_rate ?? table._default ?? 10);
}

// Comissao por FAIXA DE PRECO (mesma logica do "Code in JavaScript2"): item mais barato => % maior.
function getCommissionPriceTiers(c) {
  try {
    const raw = c.commission_price_tiers;
    const arr = Array.isArray(raw) ? raw : (typeof raw === 'string' && raw.trim() ? JSON.parse(raw) : null);
    if (Array.isArray(arr) && arr.length) return arr.slice().sort((a, b) => (Number(a.max) || 0) - (Number(b.max) || 0));
  } catch (e) {}
  return null;
}
const COMMISSION_TIERS = getCommissionPriceTiers(cfg);
function rateByPrice(p) {
  if (!COMMISSION_TIERS || !(p > 0)) return null;
  for (const t of COMMISSION_TIERS) { if (p <= (Number(t.max) || 0)) return Number(t.rate); }
  return Number(COMMISSION_TIERS[COMMISSION_TIERS.length - 1].rate);
}

// ---------- Helpers de texto / parsing ----------
function norm(s) {
  return String(s ?? '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/\s+/g, ' ').trim();
}
function titleOf(j) {
  return j?._heuristica?.title_norm || norm(j?.['Nomes Produtos'] || j?.nome || j?.title || '');
}
// "+5mil vendidos", "1,2 mil", "500 vendidos", "10 mil" -> numero
function parseSales(j) {
  if (j.sales != null && j.sales !== '') { const n = Number(j.sales); if (Number.isFinite(n)) return n; }
  const t = norm(String(j.vendas_text || '') + ' ' + String(j.vendas_text_alt || ''));
  const m = t.match(/\+?\s*([\d.,]+)\s*(mil|k)?/);
  if (!m) return 0;
  let n = parseFloat(m[1].replace(/\./g, '').replace(',', '.'));
  if (!Number.isFinite(n)) return 0;
  if (m[2]) n *= 1000;
  return Math.round(n);
}
// "4.8", "4,8" -> nota 0..5
function parseRating(j) {
  if (j.rating != null && j.rating !== '') { const n = Number(j.rating); if (Number.isFinite(n) && n <= 5) return n; }
  const t = String(j.rating_text || '').replace(',', '.');
  const m = t.match(/([0-5](?:\.\d{1,2})?)/);
  return m ? parseFloat(m[1]) : 0;
}
// Palavras "significativas" do titulo (ignora genericas/curtas/numeros)
const STOP = new Set(
  String(cfg.similar_words_stoplist ??
    'kit,kits,combo,jogo,conjunto,original,novo,nova,com,sem,para,por,pcs,pecas,peca,unidades,unidade,und,un,ml,kg,litro,litros,grama,gramas,premium,profissional,promocao,oferta,desconto,frete,gratis,the,and,uma,dos,das'
  ).split(',').map(s => norm(s)).filter(Boolean)
);
function palavras(title) {
  return norm(title).split(/[^a-z0-9]+/).filter(w => w.length >= MIN_WORD_LEN && !STOP.has(w) && !/^\d+$/.test(w));
}

// ---------- 1) Normaliza candidatos ----------
let cands = acumulados.map(j => {
  const price = Number(j.price) || 0;
  const discount = Number(j.discount_pct ?? j.discount_pct_preview ?? 0) || 0;
  const sales = parseSales(j);
  const rating = parseRating(j);
  const rate = rateByPrice(price) ?? commissionRate(j.categoria || j.categoria_origem || CATEGORIA);
  const commVal = price > 0 ? Number((price * rate / 100).toFixed(2)) : 0;
  return { j, price, discount, sales, rating, commVal };
});

const totalPool = cands.length;

// ---------- 2) Filtros duros: precisa de preco; teto de preco; comissao minima ----------
cands = cands.filter(c => c.price > 0);
if (MAX_PRICE > 0)    cands = cands.filter(c => c.price <= MAX_PRICE);
if (MIN_COMM_VAL > 0) cands = cands.filter(c => c.commVal >= MIN_COMM_VAL);

// ---------- 3) Score composto (cada sinal normalizado 0..100) ----------
const maxSales = Math.max(1, ...cands.map(c => c.sales));
const maxComm  = Math.max(1, ...cands.map(c => c.commVal));
for (const c of cands) {
  const salesN  = (c.sales / maxSales) * 100;
  const ratingN = (Math.min(c.rating, 5) / 5) * 100;
  const discN   = Math.min(c.discount, 100);
  const commN   = (c.commVal / maxComm) * 100;
  c.scoreFinal = salesN * W_SALES + ratingN * W_RATING + discN * W_DISCOUNT + commN * W_COMMISSION;
}
cands.sort((a, b) => b.scoreFinal - a.scoreFinal);

// ---------- 4) Palavras das ULTIMAS execucoes (janela WINDOW_H h), mesma categoria ----------
// "Get Existing IDs" foi lido no inicio da execucao -> reflete o que foi inserido nas runs anteriores.
let recentes = [];
try { recentes = $('Get Existing IDs').all().map(r => r.json || {}); } catch (e) { recentes = []; }
const cutoff = Date.now() - WINDOW_H * 3600 * 1000;
const palavrasBloqueadas = new Set();
for (const r of recentes) {
  const cat = String(r.categoria || '').toLowerCase().trim();
  if (CATEGORIA && cat && cat !== CATEGORIA) continue;        // so a categoria deste scraper
  const t = Date.parse(r.createdAt || r.sent_at || '') || 0;
  if (t < cutoff) continue;                                   // fora da janela (>2 execucoes atras)
  for (const w of palavras(r.productname || '')) palavrasBloqueadas.add(w);
}

// ---------- 5) Escolha com QUALIDADE (vendas + avaliacao) e sem palavra repetida ----------
// Garante "produtos tops": exige vendas e nota minimas. Se faltar para fechar FINAL_PICK,
// afrouxa em estagios — mas o ultimo estagio ainda exige vendas > 0 (nunca pega item
// desconhecido que "ninguem sabe o que e"). cands ja vem ordenado por score desc.
const escolhidos = [];
const usadasNoLote = new Set();
const idsEscolhidos = new Set();
function colide(ws) { for (const w of ws) if (palavrasBloqueadas.has(w) || usadasNoLote.has(w)) return true; return false; }
function aceita(c) {
  c.j.sales = c.sales;
  c.j.rating = c.rating;
  c.j.commission_value_estimado = c.commVal;
  c.j._rank_final = Math.round(c.scoreFinal * 100) / 100;
  escolhidos.push(c.j);
  idsEscolhidos.add(String(c.j.link_compra || ''));
  for (const w of palavras(titleOf(c.j))) usadasNoLote.add(w);
}

// Estagios de qualidade: (vendas_min, rating_min, aplica_dedup_de_palavra)
const estagiosQ = [
  { vendas: MIN_SALES,                rating: MIN_RATING,                    dedupWords: true  }, // top + bem avaliado
  { vendas: Math.ceil(MIN_SALES / 2), rating: Math.max(0, MIN_RATING - 0.3), dedupWords: true  }, // afrouxa um pouco
  { vendas: 1,                        rating: 0,                             dedupWords: true  }, // ao menos teve venda
  { vendas: 1,                        rating: 0,                             dedupWords: false }, // ultimo recurso (so se STRICT=false)
];
for (const est of estagiosQ) {
  if (escolhidos.length >= FINAL_PICK) break;
  if (!est.dedupWords && STRICT_WORDS) continue; // respeita STRICT: nao fura palavra repetida
  for (const c of cands) {
    if (escolhidos.length >= FINAL_PICK) break;
    if (idsEscolhidos.has(String(c.j.link_compra || ''))) continue; // ja escolhido em estagio anterior
    if (c.sales < est.vendas) continue;                              // vendas minimas
    if (est.rating > 0 && c.rating < est.rating) continue;           // nota minima (quando exigida)
    if (est.dedupWords && colide(palavras(titleOf(c.j)))) continue;  // evita produto "parecido"
    aceita(c);
  }
}

console.log(`[Finalizar] pool=${totalPool} | apos_filtros=${cands.length} | bloqueadas_palavras=${palavrasBloqueadas.size} | escolhidos=${escolhidos.length}/${FINAL_PICK}`);

return escolhidos.map(j => ({ json: j }));

// ===== PARSE de URL e PREÇO (sem filtro de comissão aqui) =====
// A taxa de comissão do Mercado Livre VARIA por produto/categoria/vendedor,
// então não dá pra estimar com segurança antes de chamar a API de afiliado.
// Por isso este node NÃO filtra mais por comissão — só limpa a URL e extrai o preço.
// O corte de comissão mínima acontece depois, no "Filter Already Saved",
// usando a comissão REAL (vinda da API/parse final em "Code in JavaScript2").

// ===== 1. LIMPA URL =====
function cleanMlUrl(u) {
  if (!u) return '';

  const urlParamMatch = u.match(/[?&]url=([^&]+)/i);
  if (urlParamMatch) {
    try { u = decodeURIComponent(urlParamMatch[1]); } catch(e) {}
  }

  const clickMatch = u.match(/click1\.mercadolivre\.com\.br\/mclics\/[^\/]+\/(https?:\/\/[^\s"]+)/i);
  if (clickMatch) {
    try { u = decodeURIComponent(clickMatch[1]); } catch(e) {}
  }

  if (/click1\.mercadolivre/i.test(u)) return '';

  u = u.split('#')[0].split('?')[0];
  return u;
}

// ===== 2. PARSE PREÇO =====
function parseMlPrice(str) {
  if (!str) return { price_old: null, price: null, discount_pct: null };

  let s = str
    .replace(/\d+\s*x\s*R\$\s*[\d\.,]+/gi, ' ')
    .replace(/no\s+Pix|sem\s+juros|\bou\b|\bem\b/gi, ' ');

  const tryParse = (cleaned) => {
    const matches = [...cleaned.matchAll(/R\$\s?([\d\.]+(?:,\d{1,2})?)/g)];
    return matches
      .map(m => Number(parseFloat(m[1].replace(/\./g, '').replace(',', '.')).toFixed(2)))
      .filter(n => n >= 5)
      .sort((a, b) => b - a);
  };

  const candidates = [];
  for (const re of [/(\d{2})\s*%\s*OFF/i, /(\d)\s*%\s*OFF/i]) {
    const m = s.match(re);
    if (!m) continue;
    const pct = parseInt(m[1]);
    const precos = tryParse(s.replace(m[0], ' '));
    if (precos.length >= 2) {
      const realPct = Math.round((1 - precos[1] / precos[0]) * 100);
      const diff = Math.abs(realPct - pct);
      candidates.push({ price_old: precos[0], price: precos[1], discount_pct: pct, diff });
    } else if (precos.length === 1) {
      candidates.push({ price_old: (pct > 0 && pct < 100) ? Number((precos[0] / (1 - pct / 100)).toFixed(2)) : null, price: precos[0], discount_pct: pct, diff: 99 });
    }
  }

  if (candidates.length) {
    candidates.sort((a, b) => a.diff - b.diff);
    const best = candidates[0];
    return { price_old: best.price_old, price: best.price, discount_pct: best.discount_pct };
  }

  const precos = tryParse(s);
  const _po = (precos.length >= 2 ? precos[0] : null), _pr = precos[1] ?? precos[0] ?? null;
  const _dp = (_po && _pr && _po > _pr) ? Math.round((1 - _pr / _po) * 100) : null;
  return { price_old: _po, price: _pr, discount_pct: _dp };
}

// ===== 3. PREÇOS NA ORDEM DA STRING (mesma logica do parser final) =====
function pricesInOrder(str) {
  if (!str) return [];
  const main = String(str).split(/\d+x\s*R\$/i)[0];
  const re = /R\$\s*(\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?)/g;
  const out = [];
  let m;
  while ((m = re.exec(main)) !== null) {
    const v = parseFloat(m[1].replace(/\./g, '').replace(',', '.'));
    if (!isNaN(v) && v > 0) out.push(v);
  }
  return out;
}

// ===== 3.5 NORMALIZA PRECO NUMERICO (novo parser nordic) =====
// O node "Extrair HTML" agora entrega preco/preco_antigo como numero em string
// (ex.: "39.69"). Aqui reconstruimos a string "R$ antigoR$ atual" que as
// funcoes acima esperam, sem mudar nenhuma outra regra.
function brlStr(v) {
  const n = Number(v);
  if (!isFinite(n) || n <= 0) return '';
  const [i, dd] = n.toFixed(2).split('.');
  return 'R$ ' + i.replace(/\B(?=(\d{3})+(?!\d))/g, '.') + ',' + dd;
}
function normalizaPreco(j) {
  const bruto = String(j.preco ?? j.preco_produtos ?? '');
  if (/R\$/.test(bruto)) return bruto;
  const atual = brlStr(bruto.replace(',', '.'));
  if (!atual) return bruto;
  const antigo = brlStr(String(j.preco_antigo ?? '').replace(',', '.'));
  return antigo ? antigo + atual : atual;
}

// ===== APLICA =====
const results = [];

for (const item of $input.all()) {
  const j = item.json;
  const link = cleanMlUrl(j.link_compra || j.link_produtos || '');

  if (!link) continue; // sem link não tem como gerar link de afiliado, descarta

  // descarta preço quebrado do ML: atual (2º R$) maior que o original (1º R$)
  const precoStr = normalizaPreco(j);
  const ord = pricesInOrder(precoStr);
