// Parse de sales/rating a partir de texto do ML (adicionado pelo builder Lovable)
function parseSalesText(t) {
  if (!t) return 0;
  const s = String(t).replace(/\./g, '').replace(',', '.');
  const m = s.match(/(\d[\d.]*)/);
  if (!m) return 0;
  const n = parseFloat(m[1]);
  if (/mil/i.test(s)) return Math.round(n * 1000);
  return Math.round(n) || 0;
}
function parseRatingText(t) {
  if (!t) return 0;
  const s = String(t).replace(',', '.');
  const m = s.match(/(\d(?:\.\d)?)/);
  const n = parseFloat(m && m[1]);
  return (Number.isFinite(n) && n > 0 && n <= 5) ? n : 0;
}

function numOrNull(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(String(v).replace(/\s/g, '').replace(',', '.'));
  return (Number.isFinite(n) && n > 0) ? n : null;
}
function parsePreco(str) {
  if (!str) return { price: null, priceOriginal: null, discount: null };
  const s = String(str);
  // Se vier numero puro (ex.: "39.69" do parser nordic), usa direto.
  if (!/R\$/i.test(s)) {
    const direct = numOrNull(s);
    if (direct !== null) return { price: direct, priceOriginal: null, discount: null };
  }
  const main = s.split(/\d+x\s*R\$/i)[0];
  const priceRe = /R\$\s*(\d{1,3}(?:\.\d{3})*(?:,\d{1,2})?)/g;
  const prices = [];
  let lastEnd = 0;
  let m;
  while ((m = priceRe.exec(main)) !== null) {
    const v = parseFloat(m[1].replace(/\./g, '').replace(',', '.'));
    if (!isNaN(v) && v > 0) prices.push(v);
    lastEnd = m.index + m[0].length;
  }
  const tail = main.slice(lastEnd);
  const discM = tail.match(/^\s*(\d{1,2})\s*%\s*OFF/i);
  const discount = discM ? parseInt(discM[1], 10) : null;
  let price = null, priceOriginal = null;
  if (prices.length >= 2) { priceOriginal = prices[0]; price = prices[1]; }
  else if (prices.length === 1) {
    price = prices[0];
    if (discount && discount > 0 && discount < 100) priceOriginal = Number((price / (1 - discount / 100)).toFixed(2));
  }
  let finalDiscount = discount;
  if (!finalDiscount && price && priceOriginal && priceOriginal > price) finalDiscount = Math.round((1 - price / priceOriginal) * 100);
  return { price, priceOriginal, discount: finalDiscount };
}

function extractId(url) {
  if (!url) return '';
  const m = String(url).match(/\/p\/([A-Z]+U?\d+)/i) || String(url).match(/\/up\/([A-Z]+U?\d+)/i) || String(url).match(/(MLB-?U?\d+)/i);
  return m ? m[1].replace('-', '').toUpperCase() : '';
}

