}
function shortCode(u) {
  if (!u) return '';
  const m = String(u).match(/meli\.la\/([A-Za-z0-9]+)/i) || String(u).match(/mercadolivre\.com[^\s]*\/social\/[^\/]+\?[^\s]*[?&]word=([A-Za-z0-9]+)/i);
