const CONFIG_NODE = "CONFIG ML";
const cfg = ($items(CONFIG_NODE)?.[0]?.json) ?? {};

const MIN_TOTAL          = Number(cfg.min_total          ?? 30);
const MAX_TOTAL          = Number(cfg.max_total          ?? 40);
const MAX_ITENS_CATEGORIA = Number(cfg.max_itens_categoria ?? 10);
const MAX_ITENS_MARCA    = Number(cfg.max_itens_marca    ?? 5);
const MIN_COMMISSION_VALUE = Number(cfg.min_commission_value ?? 8);

// Pesos do ranking (ajustáveis no CONFIG ML)
const W_SALES      = Number(cfg.w_sales      ?? 0.5);  // peso de vendas
const W_COMMISSION = Number(cfg.w_commission ?? 0.4);  // peso de comissão
const W_DISCOUNT   = Number(cfg.w_discount   ?? 0.1);  // peso de desconto

// ---------- Helpers ----------
function normText(s) {
  return String(s ?? "")
    .toLowerCase()
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
    .replace(/\s+/g, " ")
    .trim();
}
function getTitle(j) { return j.nome || j.title || j.name || j["Nomes Produtos"] || j["['Nomes Produtos']"] || ""; }
function getLink(j)  { return j.link_compra || j.link || j.url || ""; }
function num(v, def = 0) { const n = Number(v); return Number.isFinite(n) ? n : def; }

// Extrai vendas do título ou de campo dedicado ("+1mil vendidos", "500 vendidos", etc)
function getSales(j) {
  if (j.sales != null) return num(j.sales);
  if (j.vendas != null) return num(j.vendas);
  const t = normText(getTitle(j) + " " + (j.preco || ""));
  const m = t.match(/\+?\s*(\d+(?:\.\d+)?)\s*(mil|k)?\s*vendid/i);
  if (m) {
    let n = parseFloat(m[1].replace(",", "."));
    if (m[2]) n *= 1000;
    return Math.round(n);
  }
  return 0;
}

function getCommission(j) {
  // commission_rate em % (ex: 7 = 7%) | commission_value em R$
  return num(j.commission_rate ?? j.comissao_pct ?? 0);
}

function getCommissionValue(j) {
  // Nesse ponto do pipeline a comissão real ainda não existe (só depois da API de afiliado).
  // Mantido apenas para fins informativos no campo _dedupe (debug), retorna 0 se não houver dado.
  if (j.commission_value_estimado != null) return num(j.commission_value_estimado);
  if (j.commission_value != null) return num(j.commission_value);
  return 0;
}

function getDiscountPct(j) {
  return num(j.discount_pct ?? j.discount_pct_preview ?? 0);
}

function getCategoria(j) { return normText(j.categoria || j.category || "geral"); }
function getMarca(j)     { return normText(j.marca || j.brand || "sem_marca"); }

function getExactKey(j) {
  const title = normText(getTitle(j));
  const link  = normText(getLink(j)).split("?")[0].split("#")[0];
  return `${title}||${link}`;
}

// ---------- Score composto (normaliza vendas/comissão/desconto pra 0-100) ----------
function rankScore(j, maxSales, maxCommission) {
  const sales      = getSales(j);
  const commission = getCommission(j);
  const discount   = getDiscountPct(j);

  const salesNorm      = maxSales      > 0 ? (sales      / maxSales)      * 100 : 0;
  const commissionNorm = maxCommission > 0 ? (commission / maxCommission) * 100 : 0;
  const discountNorm   = Math.min(discount, 100);

  return (
    salesNorm      * W_SALES +
    commissionNorm * W_COMMISSION +
    discountNorm   * W_DISCOUNT
  );
}

// ---------- 1) Dedupe exato ----------
const inputItems = $input.all();
const bestByExact = new Map();

for (const it of inputItems) {
  const j = it.json ?? {};
  if (!getLink(j)) continue;
  const k = getExactKey(j);
  const prev = bestByExact.get(k);
  // Mantém o de maior venda em caso de duplicata
  if (!prev || getSales(j) > getSales(prev.json ?? {})) {
    bestByExact.set(k, it);
  }
}

const deduped = Array.from(bestByExact.values()).map(it => it.json ?? {});

// ---------- 2) Calcula máximos pra normalização ----------
// OBS: a comissão REAL só fica disponível depois da chamada de API de afiliado
// (mais adiante no pipeline). Aqui ainda não dá pra filtrar por comissão com segurança,
// já que a taxa varia por produto/vendedor. O corte de comissão mínima acontece
// no final do pipeline, no node "Filter Already Saved", com o valor real.
const maxSales      = Math.max(1, ...deduped.map(getSales));
const maxCommission = Math.max(1, ...deduped.map(getCommission));

// ---------- 3) Ordena por score composto desc ----------
const ranked = deduped
  .map(j => ({ j, _rank_score: rankScore(j, maxSales, maxCommission) }))
  .sort((a, b) => b._rank_score - a._rank_score);

// ---------- 4) Monta filas por categoria + round-robin, com limites de marca/categoria ----------
// Função reaproveitável: dado um limite de categoria e de marca, monta as filas e
// intercala (round-robin) entre as categorias, respeitando MAX_TOTAL.
function montarRoundRobin(maxItensCategoria, maxItensMarca) {
  const marcaCount = new Map();
  const filaPorCategoria = new Map(); // categoria -> array de items prontos (na ordem de score)

  for (const { j, _rank_score } of ranked) {
    const cat   = getCategoria(j);
    const marca = getMarca(j);

    const fila = filaPorCategoria.get(cat) ?? [];
    if (fila.length >= maxItensCategoria) continue;

    const mCount = marcaCount.get(marca) ?? 0;
    if (marca !== "sem_marca" && mCount >= maxItensMarca) continue;

    fila.push({
      json: {
        ...j,
        _rank_score: Math.round(_rank_score * 100) / 100,
        _dedupe: {
          sales:           getSales(j),
          commission_rate: getCommission(j),
          commission_value: getCommissionValue(j),
          discount_pct:    getDiscountPct(j),
          min_total:       MIN_TOTAL,
          max_total:       MAX_TOTAL,
          max_categoria:   maxItensCategoria,
          max_marca:       maxItensMarca,
          exact_key:       getExactKey(j),
        }
      }
    });

    filaPorCategoria.set(cat, fila);
    marcaCount.set(marca, mCount + 1);
  }

  // Round-robin: mantém a ordem de categorias como apareceram primeiro no ranking
  // (segue o round-robin de scraping definido em "Montar Links ML").
  const categoriasOrdenadas = Array.from(filaPorCategoria.keys());
  const out = [];
  let algumaFilaTemItem = true;

  while (algumaFilaTemItem && out.length < MAX_TOTAL) {
    algumaFilaTemItem = false;
    for (const cat of categoriasOrdenadas) {
      if (out.length >= MAX_TOTAL) break;
      const fila = filaPorCategoria.get(cat);
      if (fila && fila.length > 0) {
        out.push(fila.shift());
        algumaFilaTemItem = true;
      }
    }
  }

  return out;
}

// ---------- 5) Afrouxa os limites progressivamente até atingir MIN_TOTAL ----------
// Tenta primeiro com os limites normais (max_itens_categoria / max_itens_marca).
// Se não atingir o piso de MIN_TOTAL produtos, vai abrindo os limites em estágios,
// até atingir o piso ou esgotar todos os candidatos disponíveis (sempre respeitando MAX_TOTAL).
const estagios = [
  { categoria: MAX_ITENS_CATEGORIA,     marca: MAX_ITENS_MARCA     },
  { categoria: MAX_ITENS_CATEGORIA + 4, marca: MAX_ITENS_MARCA + 2 },
  { categoria: MAX_ITENS_CATEGORIA + 8, marca: MAX_ITENS_MARCA + 4 },
  { categoria: MAX_TOTAL,               marca: MAX_TOTAL           }, // sem limite efetivo
];

let out = [];
for (const estagio of estagios) {
  out = montarRoundRobin(estagio.categoria, estagio.marca);
  if (out.length >= MIN_TOTAL) break;
}

return out;

