const html = $json.data || '';
const categoriaInput = $json.categoria || '';

const vazio = {
  'Nomes Produtos': [], 'Imagem Produtos (src)': [], 'preco': [],
  'preco_antigo': [], 'desconto': [], 'link_compra': [],
  'Imagem Produtos (data-src)': [], 'Imagem Produtos (srcset)': [],
  'Imagem Produtos (data-srcset)': [], 'vendas_text': [],
  'vendas_text_alt': [], 'rating_text': [], 'categoria': [],
};

const m = html.match(/_n\.ctx\.s\.q\("0:([\s\S]*?)\\n"\);/);
if (!m) return { json: { ...vazio, _erro: 'payload nordic nao encontrado (possivel bloqueio/captcha)' } };

let s;
try { s = JSON.parse('"' + m[1] + '"'); }
catch (e) { return { json: { ...vazio, _erro: 'falha ao decodificar payload' } }; }

const cards = [];
let idx = 0;
while ((idx = s.indexOf('"results":[', idx)) !== -1) {
  const j = s.indexOf('[', idx);
  let depth = 0, k = j, inStr = false, esc = false;
  while (k < s.length) {
    const c = s[k];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
    } else {
      if (c === '"') inStr = true;
      else if (c === '[') depth++;
      else if (c === ']') { depth--; if (depth === 0) break; }
    }
    k++;
  }
  const arr = s.slice(j, k + 1).replace(/(?<=[:,\[])u(?=[,}\]])/g, 'null');
  try {
    for (const r of JSON.parse(arr)) {
      if (r && r.id === 'POLYCARD' && r.polycard) cards.push(r.polycard);
    }
  } catch (e) { /* ignora bloco invalido */ }
  idx = k;
}

if (!cards.length) return { json: { ...vazio, _erro: 'nenhuma pagina com produtos' } };

const qm = s.match(/"query":"([^"]*)"/);
const query = qm ? qm[1] : '';

const out = { ...vazio };

for (const pc of cards) {
  const meta = pc.metadata || {};

  const isAd = meta.is_pad === 'true' || meta.is_pad === true;
  let url = meta.url || '';
  if (isAd || !url || url.startsWith('click1.')) continue;
  if (!url.startsWith('http')) url = 'https://' + url;

  const comps = {};
  for (const c of (pc.components || [])) if (!comps[c.type]) comps[c.type] = c;

  const titulo = comps.title?.title?.text || '';
  const price = comps.price?.price || {};
  const atual = price.current_price?.value ?? null;
  // preco antigo: caminho conhecido + varredura profunda (o ML muda a posicao
  // do previous_price entre layouts, e sem ele o robo mandava "De X por X").
  function deepPrev(obj, depth) {
    if (!obj || typeof obj !== 'object' || (depth || 0) > 6) return null;
    if (Array.isArray(obj)) {
      for (const it of obj) { const r = deepPrev(it, (depth || 0) + 1); if (r !== null) return r; }
      return null;
    }
    const k = String(obj.key || obj.type || obj.id || '').toLowerCase();
    if (/previous_price|original_price|price_before|old_price/.test(k)) {
      const v = obj?.price?.value ?? obj?.value ?? null;
      const n = Number(v);
      if (Number.isFinite(n) && n > 0) return n;
    }
    for (const kk of Object.keys(obj)) {
      if (/previous_price|original_price|old_price/.test(kk.toLowerCase())) {
        const cand = obj[kk];
        const n = Number(cand && typeof cand === 'object' ? (cand.value ?? cand?.price?.value) : cand);
        if (Number.isFinite(n) && n > 0) return n;
      }
      const r = deepPrev(obj[kk], (depth || 0) + 1);
      if (r !== null) return r;
    }
    return null;
  }
  let antigo = price.price_labels?.[0]?.values
    ?.find(v => v.key === 'previous_price')?.price?.value ?? null;
  if (antigo === null || !(Number(antigo) > 0)) antigo = deepPrev(price, 0);
  // fallback final: reconstroi pelo % de desconto do card
  if ((antigo === null || !(Number(antigo) > 0)) && atual !== null) {
    const pctTxt = JSON.stringify(price.discount_polylabel || price.discount || '');
    const pm = pctTxt.match(/(\d{1,2})\s*%/);
    const pct = pm ? parseInt(pm[1], 10) : 0;
    if (pct > 0 && pct < 90) antigo = Number((Number(atual) / (1 - pct / 100)).toFixed(2));
  }
  if (antigo !== null && atual !== null && Number(antigo) <= Number(atual)) antigo = null;
  const pill = price.discount_polylabel?.values
    ?.find(v => v.key === 'previous_label')?.pill?.text || '';

  const alt = comps.review_compacted?.review_compacted?.alt_text || '';
  const rMatch = alt.match(/Classificação ([\d.,]+)/);
  const vendasFrase = alt.includes('vendidos')
    ? (alt.split('.').find(t => t.includes('vendidos')) || '').trim()
    : '';

  const picId = pc.pictures?.pictures?.[0]?.id || '';
  const imgUrl = picId ? `https://http2.mlstatic.com/D_NQ_NP_${picId}-O.webp` : '';

  out['Nomes Produtos'].push(titulo);
  out['Imagem Produtos (src)'].push(imgUrl);
  out['Imagem Produtos (data-src)'].push(imgUrl);
  out['preco'].push(atual !== null ? String(atual) : '');
  out['preco_antigo'].push(antigo !== null ? String(antigo) : '');
  out['desconto'].push(pill);
  out['link_compra'].push(url);
  out['vendas_text'].push(vendasFrase);
  out['vendas_text_alt'].push(vendasFrase);
  out['rating_text'].push(rMatch ? rMatch[1] : '');
  out['categoria'].push(categoriaInput || query);
}

if (!out['Nomes Produtos'].length) {
  return { json: { ...vazio, _erro: 'apenas anuncios pagos nesta pagina' } };
}

return { json: out };
